func inboxMessageTouchesMemoSet(message *storepb.InboxMessage, memoIDSet map[int32]struct{}) bool {
	if message == nil {
		return false
	}

	switch message.Type {
	case storepb.InboxMessage_MEMO_COMMENT:
		payload := message.GetMemoComment()
		if payload == nil {
